CREATE TABLE orders (id int, country text, region text, status text);
INSERT INTO orders
SELECT g,
       CASE WHEN g % 2 = 0 THEN 'US' ELSE 'DE' END AS country,
       CASE WHEN g % 2 = 0 THEN 'CA' ELSE 'BE' END AS region,
       CASE WHEN g % 5 = 0 THEN 'shipped' ELSE 'pending' END AS status
FROM generate_series(1, 20000) g;
ANALYZE orders;
CREATE STATISTICS stx_orders_geo (dependencies, mcv) ON country, region, status FROM orders;
ANALYZE orders;
